arguments.command:
python -c "
import parse
r = parse.parse('''
            letters: {:w}
            non-letters: {:W}
            whitespace: \"{s}\"
            non-whitespace: \t{:S}\n
            digits: {:d}
            non-digits: {:D}
            numbers with thousands: {:n}
            fixed-point: {:f}
            floating-point: {:e}
            general numbers: {:g} {:g}
            binary: {:b}
            octal: {:o}
            hex: {:x}
        ''', '''
            letters: abcdef_GHIJLK
            non-letters: !@#%$ *^%
            whitespace: \"   \\t\\n\"
            non-whitespace: \tabc\n
            digits: 0xabcdef
''')
print(r)
" 2>&1
